      EV.forEach(([l,c],i)=>{s+=`<text x="${LXX}" y="${ey+20+i*18}" class="t-xs" style="fill:${i===3?'var(--ink)':'var(--ink)'}">${i===3?'':'<tspan style="fill:'+c+'">● </tspan>'}${l.trim()}</text>`});
